import { dev } from '$app/environment';
import { manifest } from './manifest';

function webpPath(src: string, width: number): string {
	const name = src.replace(/^\/images\//, '').replace(/\.[^.]+$/, '');
	return `/images/webp/${name}-${width}.webp`;
}

/**
 * Responsive WebP attributes for an image from static/images.
 * Spread onto <img>: `<img {...responsive('/images/x.jpg')} sizes="..." alt="" />`
 * Variants are generated by `pnpm images`.
 */
export function responsive(src: string) {
	const entry = manifest[src];
	if (!entry) {
		if (dev) console.warn(`[responsive] ${src} missing in manifest — run pnpm images`);
		return { src };
	}
	return {
		src: webpPath(src, entry.widths.at(-1)!),
		srcset: entry.widths.map((w) => `${webpPath(src, w)} ${w}w`).join(', '),
		width: entry.width,
		height: entry.height
	};
}
